use crate::openapi::{Context, enum_variant_name, escape, properties, rust_doc, rust_field};
use serde_json::Value;
use std::collections::BTreeSet;
use std::fmt::Write as _;

pub fn generate(context: &Context<'_>) -> Result<String, String> {
    let revision_field = context.config.revision_field.as_str();
    let mut lines = vec![
        "//! Strongly typed Rentman API request and response models.".to_owned(),
        "//!".to_owned(),
        "//! This file is generated by `cargo xtask update-openapi`.".to_owned(),
        String::new(),
        "#![allow(clippy::module_name_repetitions)]".to_owned(),
        String::new(),
        "use crate::id::{Id, ItemId, Resource};".to_owned(),
        "use chrono::{DateTime, FixedOffset, NaiveDate};".to_owned(),
        "use crate::RentmanAmount;".to_owned(),
        "use crate::revision::{Revision, Revisioned};".to_owned(),
        "use rust_decimal::Decimal;".to_owned(),
        "use serde::{Deserialize, Serialize};".to_owned(),
        "use std::collections::BTreeMap;".to_owned(),
        "use url::Url;".to_owned(),
        String::new(),
    ];
    lines.extend(fixed_model_types());
    let schemas = context.schemas;
    let mut enums = String::new();
    for (name, schema) in schemas {
        for (field, field_schema) in properties(schema) {
            let Some(values) = field_schema.get("enum").and_then(Value::as_array) else {
                continue;
            };
            let enum_name = context.enum_type_name(name, field);
            let is_open = name.ends_with("Response");
            let derives = if is_open {
                "Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize"
            } else {
                "Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize"
            };
            writeln!(enums, "/// Values documented for `{name}.{field}`.\n#[derive({derives})]\npub enum {enum_name} {{").unwrap();
            let mut used = BTreeSet::new();
            if is_open {
                used.insert("Unknown".to_owned());
            }
            for value in values {
                let text = value
                    .as_str()
                    .map_or_else(|| value.to_string(), str::to_owned);
                let variant = enum_variant_name(value, &mut used);
                writeln!(
                    enums,
                    "    /// `{}`.\n    #[serde(rename = \"{}\")]\n    {variant},",
                    escape(&text),
                    escape(&text)
                )
                .unwrap();
            }
            if is_open {
                enums.push_str("    /// A value Rentman does not document, kept exactly as sent.\n    #[serde(untagged)]\n    Unknown(String),\n");
            }
            enums.push_str("}\n\n");
        }
    }
    lines.extend(enums.lines().map(str::to_owned));
    if !enums.is_empty() {
        lines.push(String::new());
    }
    for (schema_name, schema) in schemas {
        let rust_name = context.type_name(schema_name);
        let required = context.effective_required(schema_name, schema);
        let is_payload = schema_name.ends_with("Request");
        let mut derives = "Debug, Clone, PartialEq, Serialize, Deserialize".to_owned();
        if is_payload && required.is_empty() {
            derives.push_str(", Default");
        }
        lines.push(format!(
            "/// {}",
            rust_doc(
                Some(
                    schema
                        .get("description")
                        .and_then(Value::as_str)
                        .unwrap_or("")
                ),
                &format!("Rentman API schema `{schema_name}`.")
            )
        ));
        lines.push(format!("#[derive({derives})]"));
        lines.push(format!("pub struct {rust_name} {{"));
        for (field, field_schema) in properties(schema) {
            let rust_name = rust_field(field);
            let ty = context.field_type(schema_name, field, &required);
            lines.push(format!(
                "    /// {}",
                rust_doc(
                    field_schema.get("description").and_then(Value::as_str),
                    &format!("Rentman API field `{schema_name}.{field}`.")
                )
            ));
            let mut attrs = Vec::new();
            if rust_name != *field {
                attrs.push(format!("rename = \"{}\"", escape(field)));
            }
            let is_link =
                context.field_kind(schema_name, field) == Some("string") && ty.contains("Id<");
            if !required.contains(field) {
                attrs.push("default".to_owned());
                attrs.push("skip_serializing_if = \"Option::is_none\"".to_owned());
            } else if ty.starts_with("Option<") && !is_link {
                attrs.push("deserialize_with = \"std::option::Option::deserialize\"".to_owned());
            }
            if is_link {
                attrs.push(format!(
                    "with = \"crate::id::{}\"",
                    if ty.starts_with("Option<") {
                        "optional_link"
                    } else {
                        "link"
                    }
                ));
            }
            if !attrs.is_empty() {
                lines.push(format!("    #[serde({})]", attrs.join(", ")));
            }
            lines.push(format!("    pub {rust_name}: {ty},"));
        }
        if has_revision(context, schema_name, schema)? {
            lines.extend([
                "    /// Revision of the item as read; changes on every update.".to_owned(),
                format!("    #[serde(rename = \"{revision_field}\")] "),
                format!("    pub revision: Revision<{rust_name}>,"),
            ]);
        }
        lines.extend(["}".to_owned(), String::new()]);
        if is_payload && !required.is_empty() {
            lines.extend(payload_constructor(context, schema_name, schema, &required));
        }
    }
    validate_names(context)?;
    append_resource_impls(context, &mut lines);
    append_inventory(context, &mut lines)?;
    Ok(lines.join("\n"))
}

fn fixed_model_types() -> Vec<String> {
    r#"/// Marker type for endpoints without a JSON request body.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub(crate) struct NoRequest;

/// Marker type for endpoints without a JSON response body.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub(crate) struct NoContent;

/// Rentman collection response wrapper.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub(crate) struct CollectionResponse<T> {
    /// Returned collection items.
    pub data: Vec<T>,
    /// Number of items in this response.
    #[serde(rename = "itemCount")]
    pub item_count: usize,
    /// Maximum number of items in this response.
    pub limit: usize,
    /// Number of skipped items when offset pagination is used.
    #[serde(default)]
    pub offset: Option<usize>,
    /// URL for the next page when cursor pagination is used.
    #[serde(default)]
    pub next_page_url: Option<Url>,
}

/// Rentman item response wrapper.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub(crate) struct ItemResponse<T> {
    /// Returned item.
    pub data: T,
    /// Number of items in this response.
    #[serde(rename = "itemCount")]
    #[serde(default)]
    pub item_count: Option<usize>,
    /// Maximum number of items in this response.
    #[serde(default)]
    pub limit: Option<usize>,
    /// Number of skipped items when offset pagination is used.
    #[serde(default)]
    pub offset: Option<usize>,
    /// URL for the next page when cursor pagination is used.
    #[serde(default)]
    pub next_page_url: Option<Url>,
}

/// Email address string from Rentman. Empty when the address is not set.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize)]
#[serde(transparent)]
pub struct EmailAddress(String);

impl EmailAddress {
    /// Returns the email address as a string slice.
    pub fn as_str(&self) -> &str {
        &self.0
    }
}

impl<'de> Deserialize<'de> for EmailAddress {
    fn deserialize<D: serde::Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        let value = String::deserialize(deserializer)?;
        // Live payloads use an empty string when no address is set.
        if !value.is_empty() && !value.contains('@') {
            return Err(serde::de::Error::custom("Rentman email address must contain '@'"));
        }
        Ok(Self(value))
    }
}

/// Explicitly open custom fields object.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, Default)]
#[serde(transparent)]
pub struct CustomFields(pub BTreeMap<String, CustomFieldValue>);

impl CustomFields {
    /// Reads `custom_<id>` into an application-defined Rust type.
    pub fn get<T: serde::de::DeserializeOwned>(&self, id: u64) -> Result<T, crate::CustomFieldValueError> {
        let value = self.0.get(&format!("custom_{id}")).ok_or(crate::CustomFieldValueError::Missing { id })?;
        let encoded = serde_json::to_string(value).expect("CustomFieldValue contains only JSON-compatible values");
        Ok(serde_json::from_str(&encoded)?)
    }

    /// Serializes an application-defined value into `custom_<id>`.
    pub fn set<T: Serialize>(&mut self, id: u64, value: &T) -> Result<(), crate::CustomFieldValueError> {
        let encoded = serde_json::to_string(value)?;
        self.0.insert(format!("custom_{id}"), serde_json::from_str(&encoded)?);
        Ok(())
    }
}

/// Value inside Rentman's custom fields object.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(untagged)]
pub enum CustomFieldValue {
    /// Null custom field value.
    Null,
    /// Boolean custom field value.
    Bool(bool),
    /// Numeric custom field value.
    Number(Decimal),
    /// Text custom field value.
    Text(String),
    /// List custom field value.
    List(Vec<CustomFieldValue>),
    /// Object custom field value.
    Object(BTreeMap<String, CustomFieldValue>),
}"#.lines().map(str::to_owned).collect()
}

fn has_revision(context: &Context<'_>, name: &str, schema: &Value) -> Result<bool, String> {
    let revision_field = context.config.revision_field.as_str();
    let is_resource = context.is_resource_schema(name);
    if is_resource && properties(schema).contains_key(revision_field) {
        return Err(format!(
            "{name} now documents {revision_field}; review revision support"
        ));
    }
    Ok(is_resource)
}

fn payload_constructor(
    context: &Context<'_>,
    schema_name: &str,
    schema: &Value,
    required: &BTreeSet<String>,
) -> Vec<String> {
    let mut output = vec![
        format!("impl {} {{", context.type_name(schema_name)),
        "    /// Creates the payload from its required fields; every optional field".to_owned(),
        "    /// is `None` and not sent.".to_owned(),
    ];
    let params = properties(schema)
        .iter()
        .filter(|(field, _)| required.contains(*field))
        .map(|(field, _)| {
            format!(
                "{}: {}",
                rust_field(field),
                context.field_type(schema_name, field, required)
            )
        })
        .collect::<Vec<_>>();
    output.push(format!("    pub fn new({}) -> Self {{", params.join(", ")));
    output.push("        Self {".to_owned());
    for (field, _) in properties(schema) {
        let rust_name = rust_field(field);
        output.push(format!(
            "            {rust_name}{}",
            if required.contains(field) {
                ",".to_owned()
            } else {
                ": None,".to_owned()
            }
        ));
    }
    output.extend([
        "        }".to_owned(),
        "    }".to_owned(),
        "}".to_owned(),
        String::new(),
    ]);
    output
}

fn validate_names(context: &Context<'_>) -> Result<(), String> {
    let schemas = context.schemas;
    let mut names = BTreeSet::new();
    for (name, schema) in schemas {
        names.insert(context.type_name(name).to_owned());
        for (field, value) in properties(schema) {
            if value.get("enum").is_some() {
                names.insert(context.enum_type_name(name, field));
            }
        }
    }
    for name in [
        "NoRequest",
        "NoContent",
        "CollectionResponse",
        "ItemResponse",
        "Id",
        "ItemId",
        "Resource",
        "EmailAddress",
        "CustomFields",
        "CustomFieldValue",
    ] {
        if !names.insert(name.to_owned()) {
            return Err(format!("generated type names collide: {name}"));
        }
    }
    for resource in context.resources.values() {
        if !names.insert(format!("{resource}Id")) {
            return Err(format!("generated type names collide: {resource}Id"));
        }
    }
    Ok(())
}

fn append_resource_impls(context: &Context<'_>, lines: &mut Vec<String>) {
    for (collection, resource) in &context.resources {
        lines.extend([
            format!("impl Revisioned for {resource} {{"),
            "    fn id(&self) -> Id<Self> { self.id }".to_owned(),
            "    fn revision(&self) -> &Revision<Self> { &self.revision }".to_owned(),
            "}".to_owned(),
            String::new(),
            format!("impl Resource for {resource} {{"),
            format!("    const COLLECTION: &'static str = \"{collection}\";"),
            "}".to_owned(),
            String::new(),
            format!("/// ID of a [`{resource}`] item (`/{collection}/{{id}}`)."),
            format!("pub type {resource}Id = Id<{resource}>;"),
            String::new(),
        ]);
    }
    for resource in context.resources.values() {
        let (_, schema) = context.resource_schema(resource);
        let custom = properties(schema).contains_key("custom");
        lines.extend([
            format!("impl crate::CustomFieldsResource for {resource} {{"),
            format!(
                "    fn custom_fields_mut(&mut self) -> Option<&mut CustomFields> {{ {} }}",
                if custom {
                    "self.custom.as_mut()"
                } else {
                    "None"
                }
            ),
            "}".to_owned(),
            String::new(),
        ]);
    }
}

fn append_inventory(context: &Context<'_>, lines: &mut Vec<String>) -> Result<(), String> {
    lines.extend([
        "/// Every resource type and its collection path segment.".to_owned(),
        "pub const RESOURCE_COLLECTIONS: &[(&str, &str)] = &[".to_owned(),
    ]);
    let mut resources = context.resources.iter().collect::<Vec<_>>();
    resources.sort_by_key(|(_, resource)| *resource);
    for (collection, resource) in resources {
        lines.push(format!("    (\"{resource}\", \"{collection}\"),"));
    }
    lines.push("];".to_owned());
    lines.extend([
        String::new(),
        "/// Every link field (`schema`, `field`, linked collection).".to_owned(),
        "pub const LINK_FIELDS: &[(&str, &str, &str)] = &[".to_owned(),
    ]);
    for (name, schema) in context.schemas {
        for field in properties(schema).keys() {
            if context.field_kind(name, field) != Some("string") {
                continue;
            }
            let ty = context.base_type(name, field);
            let Some(target) = ty
                .strip_prefix("Id<")
                .and_then(|inner| inner.strip_suffix('>'))
            else {
                continue;
            };
            let collection = context
                .resources
                .iter()
                .find(|(_, resource)| resource == &target)
                .map(|(collection, _)| collection)
                .ok_or_else(|| format!("no collection for link target {target}"))?;
            lines.push(format!(
                "    (\"{}\", \"{}\", \"{}\"),",
                name,
                escape(field),
                collection
            ));
        }
    }
    lines.push("];".to_owned());
    lines.extend([
        String::new(),
        "/// Every Rentman API component schema and the Rust type that represents it.".to_owned(),
        "pub const SCHEMA_TYPES: &[(&str, &str)] = &[".to_owned(),
    ]);
    for name in context.schemas.keys() {
        lines.push(format!(
            "    (\"{}\", \"{}\"),",
            escape(name),
            context.type_name(name)
        ));
    }
    lines.push("];".to_owned());
    Ok(())
}

#[cfg(test)]
// Coverage is disabled for test code so the production 100% gate measures only
// generator behavior.
#[cfg_attr(coverage_nightly, coverage(off))]
mod tests {
    use super::*;
    use crate::openapi::FieldOverride;
    use crate::test_support::{config, config_with, spec};
    use serde_json::json;

    fn models(spec: &Value) -> Result<String, String> {
        generate(&Context::with_config(spec, config()).unwrap())
    }

    #[test]
    fn renders_models_enums_payload_constructors_and_inventories() {
        let code = models(&spec()).unwrap();
        for expected in [
            "pub enum WidgetStatus {",
            "    #[serde(rename = \"in use\")]\n    InUse,",
            "    #[serde(rename = \"1\")]\n    One,",
            "    #[serde(untagged)]\n    Unknown(String),",
            "#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]\npub enum WidgetPayloadStatus {",
            "/// A widget.\n#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]\npub struct Widget {",
            "    /// Display name.\n    #[serde(deserialize_with = \"std::option::Option::deserialize\")]\n    pub name: Option<String>,",
            "    #[serde(default, skip_serializing_if = \"Option::is_none\", with = \"crate::id::optional_link\")]\n    pub part: Option<Id<Part>>,",
            "    #[serde(rename = \"type\", default, skip_serializing_if = \"Option::is_none\")]\n    pub type_: Option<String>,",
            "    #[serde(with = \"crate::id::link\")]\n    pub part: Id<Part>,",
            "    pub revision: Revision<Widget>,",
            "#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, Default)]\npub struct WidgetUpdatePayload {",
            "    pub fn new(name: String) -> Self {\n        Self {\n            name,\n        }\n    }",
            "            label: None,",
            "fn custom_fields_mut(&mut self) -> Option<&mut CustomFields> { self.custom.as_mut() }",
            "fn custom_fields_mut(&mut self) -> Option<&mut CustomFields> { None }",
            "pub type WidgetId = Id<Widget>;",
            "    (\"Part\", \"parts\"),\n    (\"Widget\", \"widgets\"),",
            "    (\"WidgetResponse\", \"part\", \"parts\"),",
            "    (\"WidgetBulkRequest\", \"WidgetBulkPayload\"),",
        ] {
            assert!(code.contains(expected), "missing {expected:?}");
        }
    }

    #[test]
    fn documents_without_enums_render_no_enum_section() {
        let mut spec = spec();
        let schemas = spec["components"]["schemas"].as_object_mut().unwrap();
        schemas["WidgetResponse"]["properties"]
            .as_object_mut()
            .unwrap()
            .remove("status");
        schemas["WidgetRequest"]["properties"]
            .as_object_mut()
            .unwrap()
            .remove("status");
        schemas["WidgetRequest"]["required"] = json!(["name"]);
        let code = models(&spec).unwrap();
        assert!(!code.contains("/// Values documented for"));
        assert!(code.contains("pub(crate) struct NoRequest;"));
    }

    #[test]
    fn rejects_documented_revisions_and_colliding_names() {
        let mut spec = spec();
        spec["components"]["schemas"]["PartResponse"]["properties"]["updateHash"] =
            json!({"type": "string"});
        assert_eq!(
            models(&spec),
            Err("PartResponse now documents updateHash; review revision support".to_owned())
        );

        let mut spec = crate::test_support::spec();
        spec["components"]["schemas"]["CustomFieldsResponse"] = json!({});
        assert_eq!(
            models(&spec),
            Err("generated type names collide: CustomFields".to_owned())
        );

        let mut spec = crate::test_support::spec();
        spec["components"]["schemas"]["PartIdResponse"] = json!({});
        assert_eq!(
            models(&spec),
            Err("generated type names collide: PartId".to_owned())
        );
    }

    #[test]
    fn link_inventory_needs_a_collection_for_every_link_type() {
        let mut spec = spec();
        spec["components"]["schemas"]["PartResponse"]["properties"]["ghost"] =
            json!({"type": "string"});
        let config = config_with(|config| {
            config.response_type_overrides.push(FieldOverride {
                schema: "PartResponse".to_owned(),
                field: "ghost".to_owned(),
                rust_type: "Id<Ghost>".to_owned(),
            });
        });
        assert_eq!(
            generate(&Context::with_config(&spec, config).unwrap()),
            Err("no collection for link target Ghost".to_owned())
        );
    }
}
